def main():
    existing = set()
    for fn in os.listdir(ARTICLES):
        if fn.endswith(".html") and fn != "index.html":
            existing.add(fn.replace(".html", ""))
    
    available = [t for t in TEMPLATES if t["slug"] not in existing]
    to_generate = random.sample(available, min(20, len(available)))
    
    generated = 0
    for template in to_generate:
        html = generate_article(template)
        fp = os.path.join(ARTICLES, f"{template['slug']}.html")
        with open(fp, "w", encoding="utf-8") as f:
            f.write(html)
        print(f"  GENERATED: {template['slug']}.html")
        generated += 1
    
    print(f"\nTotal generated: {generated} articles")
    print(f"Date: {TODAY}")
    print(f"Total articles now: {len([f for f in os.listdir(ARTICLES) if f.endswith('.html')])}")

if __name__ == "__main__":
    main()
